import os

def get_env_value(key: str, default: str) -> str:
    """
    Reads a .env file and returns the value for the specified key.
    If the key is not found or the file does not exist, returns the default value.

    :param key: The key to look for in the .env file.
    :param default: The default value to return if the key is not found.
    :return: The value from the .env file or the default.
    """
    env_path = '.env'

    if not os.path.exists(env_path):
        return default

    env_vars = {}

    with open(env_path, 'r') as file:
        for line in file:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' in line:
                k, v = line.split('=', 1)
                env_vars[k.strip()] = v.strip()

    return env_vars.get(key, default)

