def find_closest_match_fuzzy(query, names_list):
    best_match = None
    best_score = 0
    for name in names_list:
        score = fuzz.ratio(query.lower(), name.lower())
        if score > best_score:
            best_score = score
            best_match = name
    return best_match if best_score > 60 else None

